import { lazy } from 'react';
import { ClipboardList as IcClipboardList, Compass as IcCompass, Gauge as IcGauge, Sprout as IcSprout, TrendingUp as IcTrendingUp } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Sourcing & Supplier Strategy — hub page for the Procurement menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 5 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'SourcingCenter'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const SourcingStrategy = lazy(() => import('./SourcingStrategy'));
const RfxEvaluation = lazy(() => import('./RfxEvaluation'));
const SupplierCapacity = lazy(() => import('./SupplierCapacity'));
const SupplierPerformanceIndex = lazy(() => import('./SupplierPerformanceIndex'));
const SupplierDevelopment = lazy(() => import('./SupplierDevelopment'));

export const TABS = [
  { id: 'strategy', label: 'Sourcing Strategy', icon: IcCompass, page: 'SourcingStrategy', Component: SourcingStrategy },
  { id: 'rfx', label: 'RFx Evaluation', icon: IcClipboardList, page: 'RfxEvaluation', Component: RfxEvaluation },
  { id: 'capacity', label: 'Supplier Capacity', icon: IcGauge, page: 'SupplierCapacity', Component: SupplierCapacity },
  { id: 'performance', label: 'Supplier Performance', icon: IcTrendingUp, page: 'SupplierPerformanceIndex', Component: SupplierPerformanceIndex },
  { id: 'development', label: 'Supplier Development', icon: IcSprout, page: 'SupplierDevelopment', Component: SupplierDevelopment },
];

export default function SourcingCenter({ setPage }) {
  return (
    <TabHub
      icon={IcCompass}
      eyebrow="Procurement"
      title="Sourcing & Supplier Strategy"
      subtitle="Category strategy, RFx scoring, supplier capacity, performance index and development plans"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
